package model; import java.io.Serializable; public class Counter implements Serializable { private static final long serialVersionUID=1L; private int counterId,serviceId; private String counterName,staffId; private boolean active=true;
 public Counter(int id,String name,int sid,String staff){counterId=id;counterName=name;serviceId=sid;staffId=staff;} public int getCounterId(){return counterId;} public int getServiceId(){return serviceId;} public String getStaffId(){return staffId;} public String getCounterName(){return counterName;} public boolean isActive(){return active;} public void setActive(boolean a){active=a;} public void setStaffId(String s){staffId=s;} public void displayCounter(){System.out.printf("%-5d %-15s Service: %-3d Staff: %-6s Active: %s%n",counterId,counterName,serviceId,staffId,active);} }
